import 'server-only'

import type { BlogComment, BlogPost } from './types'

const API_BASE_URL = 'https://jsonplaceholder.typicode.com'

/**
 * Caching options forwarded to `fetch`.
 *
 * In the App Router each call site declares its own caching behaviour, which is
 * what `getServerSideProps` (`cache: 'no-store'`) and `getStaticProps` with
 * `revalidate` (`next: { revalidate: n }`) used to express at the page level.
 */
export type PostsFetchOptions = Pick<RequestInit, 'cache' | 'next'>

function isBlogPost(value: unknown): value is BlogPost {
  return typeof value === 'object' && value !== null && typeof (value as BlogPost).id === 'number'
}

export async function getPosts(
  options: PostsFetchOptions,
  limit?: number
): Promise<BlogPost[]> {
  const url = limit
    ? `${API_BASE_URL}/posts?_limit=${limit}`
    : `${API_BASE_URL}/posts`

  const res = await fetch(url, options)
  if (!res.ok) {
    throw new Error(`Failed to fetch posts: ${res.status} ${res.statusText}`)
  }

  return (await res.json()) as BlogPost[]
}

/** Returns `null` when the post does not exist, so callers can call `notFound()`. */
export async function getPost(
  id: string,
  options: PostsFetchOptions
): Promise<BlogPost | null> {
  const res = await fetch(`${API_BASE_URL}/posts/${id}`, options)
  if (res.status === 404) {
    return null
  }
  if (!res.ok) {
    throw new Error(`Failed to fetch post ${id}: ${res.status} ${res.statusText}`)
  }

  // JSONPlaceholder answers `{}` with a 200 for ids it does not know about.
  const post: unknown = await res.json()
  return isBlogPost(post) ? post : null
}

export async function getComments(
  id: string,
  options: PostsFetchOptions
): Promise<BlogComment[]> {
  const res = await fetch(`${API_BASE_URL}/posts/${id}/comments`, options)
  if (!res.ok) {
    throw new Error(
      `Failed to fetch comments for post ${id}: ${res.status} ${res.statusText}`
    )
  }

  return (await res.json()) as BlogComment[]
}

