import { useRouter } from 'next/navigation'
import type { ReactNode } from 'react'

export interface NavigateButtonProps {
  href: string
  children: ReactNode
  className?: string
}

/**
 * Button that navigates imperatively, the App Router equivalent of the
 * `useRouter().push()` calls the Pages Router components used. `useRouter` now
 * comes from `next/navigation` and only works in Client Components.
 */
export function NavigateButton({ href, children, className }: NavigateButtonProps) {
  const router = useRouter()

  return (
    <button type="button" className={className} onClick={() => router.push(href)}>
      {children}
    </button>
  )
}

