import { Inter } from 'next/font/google'
import Link from 'next/link'
import type { ReactNode } from 'react'
import { AppProvider } from '@/components/AppProvider'
import '@/styles/globals.css'

// Replaces the manual `<link>` tags to fonts.googleapis.com that `_document.js`
// rendered. `next/font` self-hosts the files, so no preconnect is needed.
const inter = Inter({
  subsets: ['latin'],
  weight: ['400', '500', '600'],
  display: 'swap',
  variable: '--font-inter',
})

// Replaces the `<Head>` contents of `_document.js`. Pages override these values
// with their own `metadata`/`generateMetadata` exports.
export const metadata: Metadata = {
  title: 'My Blog',
  description: 'A complex blog application',
  icons: {
    icon: '/favicon.ico',
  },
}

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en" className={inter.variable}>
      <body>
        <AppProvider>
          <div className="app-container">
            <header>
              <h1>My Blog</h1>
              <nav>
                <Link href="/">Home</Link>
                <Link href="/blog">Blog</Link>
              </nav>
            </header>
            <main>{children}</main>
            <footer>
              <p>&copy; 2024 My Blog</p>
            </footer>
          </div>
        </AppProvider>
      </body>
    </html>
  )
}

