import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import { getComments, getPost, getPosts } from '@/lib/posts'
import type { PostsFetchOptions } from '@/lib/posts'

// `getStaticProps` + `revalidate: 300` becomes route segment config (ISR).
export const revalidate = 300

// Replaces `fallback: 'blocking'`. `true` is the default: ids missing from
// `generateStaticParams` are rendered on demand and then cached. Set it to
// `false` to 404 instead (the old `fallback: false`).
export const dynamicParams = true

const CACHE_OPTIONS: PostsFetchOptions = { next: { revalidate: 300 } }

interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

// Replaces `getStaticPaths`. It returns the params themselves rather than
// `{ paths: [{ params }], fallback }` objects.
export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await getPosts(CACHE_OPTIONS)

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

// Replaces the `next/head` block. Requests here are deduplicated with the ones
// in the page component below, so the post is only fetched once per render.
export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id, CACHE_OPTIONS)

  if (!post) {
    return { title: 'Post Not Found - My Blog' }
  }

  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params

  const [post, comments] = await Promise.all([
    getPost(id, CACHE_OPTIONS),
    getComments(id, CACHE_OPTIONS),
  ])

  // Replaces `return { notFound: true }` from `getStaticProps`.
  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

