'use client'

import { useEffect } from 'react'

/**
 * Replaces `pages/_error.js` for errors thrown while rendering a route segment.
 *
 * `error.tsx` must be a Client Component and receives the error plus a `reset()`
 * callback instead of the `statusCode` that `Error.getInitialProps` used to
 * derive — the App Router has no `getInitialProps`, and 404s are handled by
 * `not-found.tsx` rather than here.
 */
export default function GlobalRouteError({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <div className="error-page">
      <h1>An error occurred</h1>
      <p>Sorry, something went wrong.</p>
      <button type="button" onClick={reset}>
        Try again
      </button>
    </div>
  )
}

