import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'
import type { ApiErrorBody, ApiPost, ApiPostInput } from '@/lib/types'

/**
 * Replaces `pages/api/posts/index.js`. Instead of one default handler that
 * switches on `req.method`, a Route Handler exports one function per method and
 * returns a Web `Response`. Next.js answers unexported methods with a 405 and
 * the correct `Allow` header automatically, so the manual `else` branch is gone.
 */
export async function GET(): Promise<NextResponse<ApiPost[]>> {
  // Simulate fetching posts
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts)
}

export async function POST(
  request: NextRequest
): Promise<NextResponse<ApiPost | ApiErrorBody>> {
  // There is no `req.body` parser in Route Handlers — read the Web Request body.
  let body: ApiPostInput
  try {
    body = (await request.json()) as ApiPostInput
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const { title, content } = body ?? {}

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  // Simulate creating a post
  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

