import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'
import type {
  ApiErrorBody,
  ApiMessageBody,
  ApiPost,
  ApiPostInput,
} from '@/lib/types'

/**
 * Replaces `pages/api/posts/[id].js`. The dynamic segment arrives through the
 * second argument as a promise instead of via `req.query`.
 */
interface RouteContext {
  params: Promise<{ id: string }>
}

export async function GET(
  _request: NextRequest,
  { params }: RouteContext
): Promise<NextResponse<ApiPost>> {
  const { id } = await params

  // Simulate fetching a single post
  const post: ApiPost = {
    id: Number.parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post)
}

export async function PUT(
  request: NextRequest,
  { params }: RouteContext
): Promise<NextResponse<ApiPost | ApiErrorBody>> {
  const { id } = await params

  let body: ApiPostInput
  try {
    body = (await request.json()) as ApiPostInput
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const { title, content } = body ?? {}

  // Simulate updating a post
  const updatedPost: ApiPost = {
    id: Number.parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost)
}

export async function DELETE(
  _request: NextRequest,
  { params }: RouteContext
): Promise<NextResponse<ApiMessageBody>> {
  const { id } = await params

  // Simulate deleting a post
  return NextResponse.json({ message: `Post ${id} deleted successfully` })
}

